                        if (true)
                        {
                            ip = code + instr.A;
                            continue;
                        }
                        break;
                    }
                    case RegisterOp.JumpLoop:
                    {
                        if (true)
                        {
                            ip = code + instr.A;
                            if (--poll == 0) { reason = NativeExit.Poll; goto Leave; }
                            continue;
                        }
                        break;
                    }
                    case RegisterOp.BrIf:
                    {
                        if (fp[instr.A].valueI32 != 0)
                        {
                            ip = code + instr.B;
                            continue;
                        }
                        break;
                    }
                    case RegisterOp.BrIfLoop:
                    {
                        if (fp[instr.A].valueI32 != 0)
                        {
                            ip = code + instr.B;
                            if (--poll == 0) { reason = NativeExit.Poll; goto Leave; }
                            continue;
                        }
                        break;
                    }
                    case RegisterOp.BrIfZero:
                    {
                        if (fp[instr.A].valueI32 == 0)
                        {
                            ip = code + instr.B;
                            continue;
                        }
                        break;
                    }
                    case RegisterOp.BrIfZeroLoop:
                    {
                        if (fp[instr.A].valueI32 == 0)
                        {
                            ip = code + instr.B;
                            if (--poll == 0) { reason = NativeExit.Poll; goto Leave; }
                            continue;
                        }
                        break;
                    }

                    default:
                        reason = NativeExit.InvalidOperation;
                        goto Leave;
                }

                ip++;
                continue;

                Leave:
                state->Function = function;
                state->Ip = ip;
                state->FrameBase = (int)(fp - v0);
                state->Fuel = fuel;
                state->Poll = poll;
                state->ActivationCount = activationCount;
                return reason;
            }
        }
    }
}
#endif
